/* Coffee and tea, the house's page (18 October 2026): every coffee drink and
   tea a guest may ask for, under the house's tab at #/menu/brew, a detail at
   #/menu/brew/<id>. The data is js/data-brew.js (BREW_GUIDE), GENERATED by
   tools/brew/build-brew.mjs from reviewed fragments and never hand-edited.

   Every method is a general method, not the house build. The house's own
   coffees are read live from the current house by id (hsCurrent): only what
   its menus print, its name read from the house and never written here. A
   lineup question is read live from the pack by its id, with the fragment's
   words when the pack lacks it. Recall cards keep their own key space
   ('Brew Guide \u00b7 <id>/make') outside allDrinks, Due today and the levels;
   the quiz writes one progress.quizzes row and nothing else. Videos are
   external links only: no frame, no picture, nothing asked of YouTube on
   render. Top level is function declarations only. */
function brewData(){ return typeof BREW_GUIDE === 'undefined' || !BREW_GUIDE ? { groups: [], house: { ids: [], teaAsk: '' }, asks: {}, companies: [], entries: [] } : BREW_GUIDE; }
function brewEntries(){ return Array.isArray(brewData().entries) ? brewData().entries : []; }
function brewEntry(id){ return brewEntries().find(function(e){ return e.id === id; }) || null; }
function brewGroups(){ return Array.isArray(brewData().groups) ? brewData().groups : []; }
function brewGroup(id){ return brewGroups().find(function(g){ return g.id === id; }) || null; }
function brewGroupTitle(id){ const g = brewGroup(id); return g ? g.title : ''; }
function brewState(){ if(!state.brew) state.brew = { item: '', q: '', group: 'all' }; return state.brew; }
function brewHref(id){ return '#/menu/brew' + (id ? '/' + encodeURIComponent(id) : ''); }
function brewBoundary(){ return 'A general method, not the house build.'; }
function brewSafeUrl(value){ try { const url = new URL(value); return url.protocol === 'https:' ? url.href : ''; } catch(e){ return ''; } }
function brewParas(value){ return String(value || '').split(/\n+/).filter(Boolean).map(function(p){ return '<p>' + esc(p) + '</p>'; }).join(''); }

/* ---- the house, read live ------------------------------------------------- */
function brewHouse(){ return typeof hsCurrent === 'function' ? hsCurrent() : null; }
function brewHouseName(){ const h = brewHouse(); return h && typeof h.name === 'string' ? h.name.trim() : ''; }
/* the {house} token a copied ask carries, filled from the house's own name */
function brewFill(text){ return String(text || '').split('{house}').join(brewHouseName() || 'the house'); }
function brewHouseItem(id){
  const h = brewHouse();
  if(!h || !id) return null;
  return [].concat(h.cocktails || [], h.dishes || []).find(function(x){ return x && x.id === id; }) || null;
}
/* the printed ingredients: the person's kept list where there is one, else the printed spec */
function brewPrinted(item){
  const kept = item && item.ingredientsNamed && item.ingredientsNamed.by === 'person' && Array.isArray(item.ingredientsNamed.value) ? item.ingredientsNamed.value : null;
  return (kept || (Array.isArray(item && item.spec) ? item.spec : [])).filter(function(s){ return typeof s === 'string' && s.trim(); });
}
/* the house's own coffees that the current house holds, in the order its
   menus print them: the house's own order, never the guide's list */
function brewHouseRows(){
  const h = brewHouse();
  const ids = (brewData().house && brewData().house.ids) || [];
  const order = [].concat((h && h.cocktails) || [], (h && h.dishes) || []).map(function(x){ return x && x.id; });
  return ids.map(function(id){ const item = brewHouseItem(id); return item && item.name ? { id: id, item: item, at: order.indexOf(id) } : null; })
    .filter(Boolean).sort(function(a, b){ return a.at - b.at; }).map(function(r){ return { id: r.id, item: r.item }; });
}
function brewTeaching(id){
  return brewEntries().filter(function(e){ const h = e.house || {}; return (h.printed && (h.packIds || []).indexOf(id) >= 0) || (h.uses || []).indexOf(id) >= 0; });
}
function brewLineup(id){
  const h = brewHouse();
  const a = h && id ? (h.askAtLineup || []).find(function(x){ return x && x.id === id; }) : null;
  return a && typeof a.question === 'string' && a.question.trim() ? a.question.trim() : '';
}
/* the lineup question for an entry: the pack's, by id, else the fragment's own words */
function brewAskText(e){
  const live = brewLineup(e && e.house && e.house.askId);
  if(live) return { text: live, live: true };
  let t = brewFill(e && e.house && e.house.ask);
  if(/^Not printed on the menus:\s*/.test(t)){ t = t.replace(/^Not printed on the menus:\s*/, ''); t = t.charAt(0).toUpperCase() + t.slice(1); }
  else if(/^Not printed on the menus and not poured at the house:\s*/.test(t)) t = 'Not poured at the house either: ' + t.replace(/^Not printed on the menus and not poured at the house:\s*/, '');
  return { text: t, live: false };
}
function brewHouseRowHTML(r, level, exceptId){
  const it = r.item, hx = level || 'h4';
  const printed = brewPrinted(it);
  const teach = brewTeaching(r.id).filter(function(e){ return e.id !== exceptId; });
  const compass = typeof barCompassDrink === 'function' && barCompassDrink(r.id) && typeof barCompassHref === 'function';
  return '<article class="brew-house-row" data-house-id="' + esc(r.id) + '"><div class="eyebrow">' + esc(it.section || 'On the menu') + '</div>'
    + '<' + hx + ' class="brew-house-name">' + esc(it.name) + (it.price ? ' <span class="brew-price">' + esc(it.price) + '</span>' : '') + '</' + hx + '>'
    + (printed.length ? '<p class="brew-printed"><span class="brew-label">As printed</span> ' + esc(printed.join(', ')) + '</p>' : '')
    + '<div class="brew-links">'
    + (it.id && /^b-/.test(it.id) ? '<button class="btn btn-ghost" data-act="brew-house" data-id="' + esc(r.id) + '">Open the house card</button>' : '')
    + (compass ? '<a class="btn btn-ghost" href="' + esc(barCompassHref(r.id)) + '">In The Bar Compass</a>' : '')
    + '</div>'
    + (teach.length ? '<p class="brew-label">How it is made, in general</p><div class="brew-links brew-teach">' + teach.map(function(e){ return '<a class="btn btn-ghost" href="' + esc(brewHref(e.id)) + '">' + esc(e.name) + '</a>'; }).join('') + '</div>' : '')
    + '</article>';
}
function brewTeaNoteHTML(){
  const q = brewLineup(brewData().house && brewData().house.teaAsk);
  return '<div class="brew-tea-note"><p class="brew-not">No tea is printed on the menus; ask at lineup.</p>'
    + '<p><span class="brew-label">The lineup question</span> ' + esc(q || 'Which teas does the house pour, hot and iced, and how is each served?') + '</p></div>';
}
/* the At the house group on the index: the house's coffees, then the tea note */
function brewAtHouseHTML(q){
  const rows = brewHouseRows().filter(function(r){ return !q || [r.item.name, r.item.section].concat(brewPrinted(r.item)).join(' ').toLowerCase().indexOf(q) >= 0; });
  const loaded = !!brewHouse();
  if(q && !rows.length) return '';
  return '<section class="brew-group brew-at-house" aria-labelledby="brew-g-house"><h3 class="brew-group-h" id="brew-g-house">' + esc(brewGroupTitle('house') || 'At the house') + '</h3>'
    + (loaded ? '<p class="brew-caption">The house\u2019s own coffees, as its menus print them, in menu order.</p>' : '<p class="brew-caption">The house\u2019s own coffees show here once the house has loaded on this device.</p>')
    + '<div class="brew-house-rows">' + rows.map(function(r){ return brewHouseRowHTML(r, 'h4'); }).join('') + '</div>'
    + (q ? '' : brewTeaNoteHTML()) + '</section>';
}
/* the detail's At the house: the live rows, or not printed and the lineup question */
function brewDetailHouseHTML(e){
  const h = e.house || {};
  let body;
  if(h.printed){
    const rows = (h.packIds || []).map(function(id){ const item = brewHouseItem(id); return item && item.name ? { id: id, item: item } : null; }).filter(Boolean);
    body = '<p class="brew-on">Printed on the menus.</p>'
      + (rows.length ? rows.map(function(r){ return brewHouseRowHTML(r, 'h4', e.id); }).join('') : '<p class="brew-caption">The house\u2019s own record shows here once the house has loaded on this device.</p>');
  } else {
    const ask = brewAskText(e);
    const uses = (h.uses || []).map(function(id){ const item = brewHouseItem(id); return item && item.name ? { id: id, item: item } : null; }).filter(Boolean);
    body = '<p class="brew-not">Not printed on the menus.</p>'
      + (ask.text ? '<p class="brew-ask"><span class="brew-label">' + (ask.live ? 'The lineup question' : 'At lineup') + '</span> ' + esc(ask.text) + '</p>' : '')
      + (uses.length ? '<div class="brew-uses"><p class="brew-label">On the menus it appears in</p>' + uses.map(function(r){
        const dish = /^d-/.test(r.id);
        const href = dish && typeof hsRoomHref === 'function' ? hsRoomHref('table', r.id, brewHouse()) : '';
        return '<p class="brew-use"><strong>' + (dish && typeof hsRoomLink === 'function' ? hsRoomLink('table', href, r.item.name) : esc(r.item.name)) + '</strong>'
          + (r.item.section ? ' <span class="brew-soft">' + esc(r.item.section) + '</span>' : '')
          + (dish ? '' : ' <button class="btn btn-ghost" data-act="brew-house" data-id="' + esc(r.id) + '">Open the house card</button>') + '</p>';
      }).join('') + '</div>' : '');
  }
  return '<section class="brew-panel brew-house" aria-labelledby="brew-d-house"><h3 id="brew-d-house">At the house</h3>' + body + '</section>';
}

/* ---- the links out ------------------------------------------------------------- */
function brewLibraryHTML(e){
  const lib = e.library || {}, out = [];
  const ref = lib.ref && typeof COFFEE_REF !== 'undefined' ? COFFEE_REF.find(function(r){ return r.name === lib.ref; }) : null;
  if(ref) out.push('<button class="btn btn-ghost" data-act="brew-lib" data-sec="' + esc(ref.dom) + '" data-ref="' + esc(ref.name) + '">The ' + esc(ref.name) + ' card</button>');
  (lib.study || []).forEach(function(pair){
    const sec = typeof COFFEE_STUDY !== 'undefined' ? COFFEE_STUDY.find(function(s){ return s.key === pair[0]; }) : null;
    const i = sec ? sec.rows.findIndex(function(r){ return r[0] === pair[1]; }) : -1;
    if(i >= 0) out.push('<button class="btn btn-ghost" data-act="brew-lib" data-sec="' + esc(sec.key) + '" data-row="' + i + '">' + esc(sec.rows[i][0]) + ' <span class="brew-soft">' + esc(sec.title) + '</span></button>');
  });
  const c = lib.cocktail && typeof COCKTAILS !== 'undefined' ? COCKTAILS.find(function(x){ return x.name === lib.cocktail; }) : null;
  if(c) out.push('<a class="btn btn-ghost" href="#/library/' + esc(slugify(c.name)) + '">The ' + esc(c.name) + ' in the Library</a>');
  const na = lib.na && typeof NA_DRINKS !== 'undefined' ? NA_DRINKS.find(function(x){ return x.name === lib.na; }) : null;
  if(na) out.push('<a class="btn btn-ghost" href="#/na/' + esc(slugify(na.name)) + '">' + esc(na.name) + ', zero proof</a>');
  const m = lib.method && typeof methodStudy === 'function' ? methodStudy(lib.method) : null;
  if(m && typeof methodStudyHref === 'function') out.push('<a class="btn btn-ghost" href="' + esc(methodStudyHref(m.id)) + '">' + esc(m.title) + '</a>');
  return out.length ? '<section class="brew-panel" aria-labelledby="brew-d-lib"><h3 id="brew-d-lib">In the Library</h3><div class="brew-links">' + out.join('') + '</div></section>' : '';
}
function brewVideoHTML(e){
  const v = e.video, off = typeof navigator !== 'undefined' && navigator && navigator.onLine === false;
  const url = v ? brewSafeUrl(v.url) : '';
  const search = (typeof ytSearch === 'function' ? ytSearch : function(q){ return 'https://www.youtube.com/results?search_query=' + encodeURIComponent(q); })(String(e.search || e.name) + (typeof scopeSuffix === 'function' ? scopeSuffix() : ''));
  const company = v && v.channelKind === 'company' && v.channel && (brewData().companies || []).indexOf(v.channel) >= 0;
  return '<section class="brew-panel brew-watch" aria-labelledby="brew-d-watch"><h3 id="brew-d-watch">Watch</h3>'
    + (url ? '<a class="btn btn-ghost brew-video" href="' + esc(url) + '" target="_blank" rel="noopener noreferrer">' + esc(v.label) + '<span class="sr-only"> (opens YouTube in a new tab)</span></a>'
      + (company ? '<p class="brew-soft">From ' + esc(v.channel) + '</p>' : '')
      + (v.watchFor ? '<p><span class="brew-label">Watch for</span> ' + esc(v.watchFor) + '</p>' : '') : '<p class="brew-caption">No video is pinned for this one yet.</p>')
    + '<p class="brew-caption">' + (off ? 'You are offline: a video needs a connection.' : 'A video opens on YouTube and needs a connection.') + '</p>'
    + '<a class="btn btn-ghost brew-search-video" href="' + esc(search) + '" target="_blank" rel="noopener noreferrer">Search for another video<span class="sr-only"> (opens YouTube in a new tab)</span></a></section>';
}
function brewTableHTML(e){
  const slug = e.table && e.table.recipe;
  if(!slug) return '';
  const name = String(slug).replace(/-/g, ' ').replace(/^./, function(c){ return c.toUpperCase(); });
  const href = typeof hsShared === 'function' && hsShared() ? '/table/recipe/' + encodeURIComponent(slug) : '';
  const link = typeof hsRoomLink === 'function' ? hsRoomLink('table', href, name) : esc(name);
  return '<section class="brew-panel" aria-labelledby="brew-d-table"><h3 id="brew-d-table">In the World Table</h3><p>The recipe: ' + link + '</p></section>';
}
function brewSourcesHTML(e){
  const rows = (e.sources || []).filter(function(s){ return s && s.title; });
  if(!rows.length) return '';
  return '<details class="brew-sources"><summary>Sources</summary><ul>' + rows.map(function(s){
    const href = s.url ? brewSafeUrl(s.url) : '';
    return '<li>' + (href ? '<a href="' + esc(href) + '" target="_blank" rel="noopener noreferrer">' + esc(s.title) + '<span class="sr-only"> (opens in a new tab)</span></a>' : esc(s.title)) + '</li>';
  }).join('') + '</ul><p class="brew-caption">Reading the sources needs a connection. In-app sources are the Library\u2019s lessons and cards and the World Table.</p></details>';
}

/* ---- the cards, the decks and the quiz ---------------------------------------- */
function brewCards(scope){
  let list = brewEntries();
  if(scope === 'coffee' || scope === 'tea' || scope === 'cocoa') list = list.filter(function(e){ return e.kind === scope; });
  else if(scope && scope.indexOf('group:') === 0) list = list.filter(function(e){ return e.group === scope.slice(6); });
  else if(scope && scope.indexOf('item:') === 0) list = list.filter(function(e){ return e.id === scope.slice(5); });
  const cards = [];
  list.forEach(function(e){ (e.recall || []).forEach(function(r){
    cards.push({ src: 'Brew Guide', name: r.prompt, back: r.answer, group: e.name, spec: [], brewKey: e.id + '/' + r.id, itemId: e.id, drillId: r.id, ref: { id: e.id } });
  }); });
  return cards;
}
function brewCardByKey(key){ return brewCards().find(function(c){ return 'Brew Guide \u00b7 ' + c.brewKey === key; }) || null; }
function brewRecord(card, now){
  now = now === undefined ? Date.now() : now;
  const rec = progress.cards && progress.cards['Brew Guide \u00b7 ' + card.brewKey];
  const last = Number(rec && rec.last), due = Number(rec && rec.due);
  const validLast = Number.isFinite(last) && last > 0 && last <= now;
  return { record: rec, last: validLast ? last : 0, today: validLast && new Date(last).toDateString() === new Date(now).toDateString(),
    due: !!rec && Number.isFinite(due) && due > 0 && due <= now, missed: !!rec && rec.w > 0 && rec.reps === 0 };
}
function brewDeckDef(id){
  id = String(id || '');
  let name = 'Coffee and tea', cards;
  if(id === 'brew') cards = brewCards();
  else if(id === 'brew:again'){ name = 'Coffee and tea: due or missed'; const now = Date.now(); cards = brewCards().filter(function(c){ const s = brewRecord(c, now); return s.due || s.missed; }); }
  else if(id === 'brew:coffee'){ name = 'Coffee and tea: the coffees'; cards = brewCards('coffee'); }
  else if(id === 'brew:tea'){ name = 'Coffee and tea: the teas'; cards = brewCards('tea'); }
  else if(id.indexOf('brew:group:') === 0){
    const g = brewGroup(id.slice(11));
    if(!g || g.id === 'house') return null;
    name = 'Coffee and tea: ' + g.title; cards = brewCards('group:' + g.id);
  } else return null;
  return { name: name, preset: { only: cards, deckModes: ['brew'], ordered: false }, house: true };
}
/* the card faces: a blind front, the answer and the boundary after Flip */
function brewRecallHTML(card, flipped, head, front, answer, grade){
  const e = brewEntry(card.itemId);
  const heading = '<div class="eyebrow">' + esc(e ? brewGroupTitle(e.group) : 'Coffee and tea') + ' \u00b7 Coffee and tea</div>';
  const question = '<div class="brew-question">' + esc(card.name) + '</div>';
  if(!flipped) return '<div class="col">' + head + '<div class="panel p5 col tc study-face">' + front + heading + question
    + '<p class="small dim">Say how you would make it, out loud, then flip.</p><button class="btn btn-brass" data-act="fc-flip">Flip</button></div></div>';
  return '<div class="col">' + head + '<div class="panel p5 col study-face">' + answer + heading + question + '<div class="brew-answer">' + brewParas(card.back) + '</div>'
    + '<p class="brew-boundary">' + brewBoundary() + '</p>'
    + '<a class="btn btn-ghost brew-read-link" href="' + esc(brewHref(card.itemId)) + '">Learn why: read the full entry</a>' + grade + '</div></div>';
}
/* Ten entries round-robin across the groups (the group order shuffled each
   round), one of each entry's three questions, its options shuffled. Each
   question carries the entry's card key and no bank key, so a round writes
   one progress.quizzes row and nothing reaches progress.qa or a level.
   Fewer entries deal what there is. */
function brewQuizRound(){
  const lists = shuffle(brewGroups().filter(function(g){ return g.id !== 'house'; }).map(function(g){
    return shuffle(brewEntries().filter(function(e){ return e.group === g.id && (e.quiz || []).length && (e.recall || []).some(function(r){ return r.id === 'make'; }); }));
  })).filter(function(l){ return l.length; });
  const picked = [];
  for(let i = 0; picked.length < 10 && lists.some(function(l){ return l.length > i; }); i++){
    lists.forEach(function(l){ if(picked.length < 10 && l[i]) picked.push(l[i]); });
  }
  return picked.map(function(e){
    const q = e.quiz[Math.floor(Math.random() * e.quiz.length)];
    return { prompt: q.q, options: shuffle(q.options.slice()), answer: q.options[q.a], explain: q.explain, ckey: 'Brew Guide \u00b7 ' + e.id + '/make', brewId: e.id };
  });
}

/* the Practise row's line: what a round deals with the entries here */
function brewQuizLine(){
  const n = Math.min(10, brewEntries().filter(function(e){ return (e.quiz || []).length; }).length);
  return n >= 10 ? 'Ten questions, one entry from each group in turn. It changes no level.'
    : n ? 'One question on each entry here, across the groups. It changes no level.' : 'The quiz opens once the entries are here.';
}

/* ---- the addresses -------------------------------------------------------------- */
function brewOpen(id){
  const s = brewState();
  state.tab = 'menu'; state.menu.view = 'brew';
  s.item = brewEntry(id) ? id : '';
}
function brewRoute(parts){
  if(parts[0] !== 'menu' || parts[1] !== 'brew') return false;
  let id = '';
  try { id = decodeURIComponent(parts[2] || ''); } catch(e){}
  brewOpen(id);
  return true;
}
function brewRouteNow(){ const s = brewState(); const hash = brewHref(brewEntry(s.item) ? s.item : ''); return { hash: hash, key: hash.slice(2) }; }
/* A revealed card or a round's results can open the entry that launched
   them: reference reading, so the run stays in the history for Back. */
function brewReference(prevKey){
  return !!(state.tab === 'menu' && state.menu.view === 'brew' && state.brew && state.brew.item && /^(flashcards|quiz)\//.test(prevKey || ''));
}

/* ---- the screens ---------------------------------------------------------------- */
function brewDoorHTML(){
  return '<a class="brew-door" href="' + brewHref() + '"><span class="eyebrow">Know every cup a guest asks for</span><strong>Coffee and tea</strong><span>'
    + brewEntries().length + ' coffees and teas: what each is, how it is made, what to say and a video, with the house\u2019s own coffees first.</span></a>';
}
function brewSearchText(e){
  return [e.name, (e.aka || []).join(' '), brewGroupTitle(e.group), e.kind, e.what, e.taste].join(' ').toLowerCase();
}
function brewFirstSentence(text){ const m = String(text || '').match(/^.*?[.!?](?=\s|$)/); return m ? m[0] : String(text || ''); }
function brewRowHTML(e){
  const printed = e.house && e.house.printed;
  /* the id is the row's focus signature (app.js focusSignature), so Back from an entry puts the focus on it again */
  return '<a class="brew-row" id="brew-r-' + esc(e.id) + '" href="' + esc(brewHref(e.id)) + '"><span class="brew-row-name">' + esc(e.name) + '</span>'
    + '<span class="brew-row-line">' + esc(brewFirstSentence(e.taste)) + '</span>'
    + '<span class="brew-row-foot">' + (printed ? 'Printed on the menus' : 'Not printed: ask at lineup') + '</span></a>';
}
function brewResultsHTML(){
  const s = brewState(), q = String(s.q || '').trim().toLowerCase();
  const g = s.group === 'all' || brewGroup(s.group) ? s.group : 'all';
  const all = brewEntries();
  const shown = all.filter(function(e){ return (g === 'all' || e.group === g) && (!q || brewSearchText(e).indexOf(q) >= 0); });
  const house = g === 'all' || g === 'house' ? brewAtHouseHTML(q) : '';
  const groups = brewGroups().filter(function(x){ return x.id !== 'house' && (g === 'all' || g === x.id); }).map(function(x){
    const rows = shown.filter(function(e){ return e.group === x.id; });
    return rows.length ? '<section class="brew-group" aria-labelledby="brew-g-' + esc(x.id) + '"><h3 class="brew-group-h" id="brew-g-' + esc(x.id) + '">' + esc(x.title) + ' <span class="brew-soft">\u00b7 ' + rows.length + '</span></h3><div class="brew-rows">' + rows.map(brewRowHTML).join('') + '</div></section>' : '';
  }).join('');
  /* At the house alone shows the house's own coffees, not the guide's entries, so its count is theirs */
  const hn = g === 'house' ? brewHouseRows().filter(function(r){ return !q || [r.item.name, r.item.section].concat(brewPrinted(r.item)).join(' ').toLowerCase().indexOf(q) >= 0; }).length : 0;
  const count = g === 'house' ? hn + (hn === 1 ? ' coffee' : ' coffees') + ' at the house'
    : shown.length + ' of ' + all.length + ' coffees and teas' + (g !== 'all' ? ' in ' + esc(brewGroupTitle(g)) : '');
  return '<p class="brew-caption brew-count" role="status">' + count + (q ? ' matching \u201c' + esc(s.q) + '\u201d' : '') + '.</p>'
    + house + groups + (!house && !groups ? '<p class="brew-empty">Nothing matches. Try another name, or choose every group.</p>' : '');
}
function brewChipsHTML(){
  const s = brewState();
  const chips = [['all', 'Everything']].concat(brewGroups().map(function(g){ return [g.id, g.title]; }));
  return '<nav class="brew-chips" aria-label="Groups">' + chips.map(function(c){
    const on = (s.group || 'all') === c[0];
    return '<button class="chip' + (on ? ' on' : '') + '" data-act="brew-group" data-k="' + esc(c[0]) + '" aria-pressed="' + (on ? 'true' : 'false') + '">' + esc(c[1]) + '</button>';
  }).join('') + '</nav>';
}
function brewIndexHTML(){
  const s = brewState(), house = brewHouseName();
  const cards = brewCards().length, qs = brewEntries().reduce(function(n, e){ return n + (e.quiz || []).length; }, 0);
  return '<div class="brew-index"><header class="brew-heading"><div class="eyebrow">' + esc(house ? house + ' \u00b7 Coffee and tea' : 'Coffee and tea') + '</div><h2 tabindex="-1">Coffee and tea</h2>'
    + '<p>Every coffee and tea a guest may ask for: what it is, how it is made, what to say at the table, and a video. The house\u2019s own coffees come first, as its menus print them.</p>'
    + '<p class="brew-caption">' + brewEntries().length + ' coffees and teas \u00b7 ' + cards + ' recall cards \u00b7 ' + qs + ' quiz questions</p></header>'
    + '<div class="brew-practice"><button class="btn btn-brass" data-act="brew-practise" data-deck="brew">Practise the cards</button>'
    + '<button class="btn btn-ghost" data-act="quiz-go" data-m="brew">Take the quiz</button>'
    + '<button class="btn btn-ghost" data-act="deck" data-deck="brew:again">Due or missed</button></div>'
    + '<p class="brew-boundary">Each method here is a general method, not the house build. The house\u2019s own drinks show only what its menus print; confirm the rest at lineup.</p>'
    + '<div class="brew-search"><label for="brew-q">Find a coffee or tea</label><input class="input" type="search" id="brew-q" value="' + esc(s.q || '') + '" placeholder="A name, or a word like milk or iced" autocomplete="off"></div>'
    + brewChipsHTML()
    + '<div id="brew-results">' + brewResultsHTML() + '</div>'
    + '<p class="brew-caption">The cards and the quiz keep their own record: they change no level, no Due today and no menu card.</p></div>';
}
function brewMakeHTML(e){
  const m = e.make || {};
  const facts = [['Ratio', m.ratio], ['Dose', m.dose], ['Temperature', m.temp], ['Time', m.time], ['The cup', m.cup]].filter(function(r){ return r[1]; });
  return '<section class="brew-panel brew-make" aria-labelledby="brew-d-make"><h3 id="brew-d-make">How to make it</h3>'
    + (facts.length ? '<dl class="brew-facts">' + facts.map(function(r){ return '<dt>' + r[0] + '</dt><dd>' + esc(r[1]) + '</dd>'; }).join('') + '</dl>' : '')
    + '<ol class="brew-steps">' + (m.steps || []).map(function(s){ return '<li>' + esc(s) + '</li>'; }).join('') + '</ol>'
    + '<p class="brew-boundary">' + brewBoundary() + '</p></section>';
}
function brewDetailHTML(e){
  const say = e.respell ? '<p class="brew-say"><span class="brew-label">Say it</span> ' + esc(e.respell) + '</p>' : '';
  const aka = (e.aka || []).length ? '<p class="brew-aka"><span class="brew-label">Also asked for as</span> ' + esc(e.aka.join(', ')) + '</p>' : '';
  const sec = function(id, title, html){ return '<section class="brew-panel" aria-labelledby="brew-d-' + id + '"><h3 id="brew-d-' + id + '">' + title + '</h3>' + html + '</section>'; };
  return '<article class="brew-detail"><header class="brew-heading"><div class="eyebrow">Coffee and tea \u00b7 ' + esc(brewGroupTitle(e.group)) + '</div><h2 tabindex="-1">' + esc(e.name) + '</h2>'
    + say + aka + '<p class="brew-caffeine"><span class="brew-label">Caffeine</span> ' + esc(e.caffeine) + '</p></header>'
    + '<div class="brew-practice"><button class="btn btn-brass" data-act="brew-practise" data-deck="brew:group:' + esc(e.group) + '">Practise this group</button>'
    + '<button class="btn btn-ghost" data-act="quiz-go" data-m="brew">Take the quiz</button>'
    + '<a class="btn btn-ghost" href="' + brewHref() + '">All coffee and tea</a></div>'
    + brewDetailHouseHTML(e)
    + sec('what', 'What it is', brewParas(e.what))
    + sec('taste', 'How it tastes', brewParas(e.taste))
    + brewMakeHTML(e)
    + sec('serve', 'At the table', brewParas(e.serve))
    + sec('guest', 'What to say', '<blockquote>' + esc(e.guest) + '</blockquote>')
    + sec('watchfor', 'Watch for', '<ul>' + (e.watch || []).map(function(w){ return '<li>' + esc(w) + '</li>'; }).join('') + '</ul>')
    + sec('story', 'The story', brewParas(e.story))
    + brewVideoHTML(e)
    + brewLibraryHTML(e)
    + brewTableHTML(e)
    + sec('recall', 'Recall before you reveal', (e.recall || []).map(function(r){ return '<details class="brew-recall"><summary>' + esc(r.prompt) + '</summary>' + brewParas(r.answer) + '</details>'; }).join('')
      + '<p class="brew-caption">Reading this answer is unscored. Practise this group to record a recall.</p>')
    + brewSourcesHTML(e)
    + '</article>';
}
function renderBrew(){
  const e = brewEntry(brewState().item);
  return e ? brewDetailHTML(e) : brewIndexHTML();
}

/* ---- the acts, the paint, the search, the keys ------------------------------------ */
function brewAct(act, data){
  if(act === 'brew-practise'){
    if(!openDeck(data.deck || 'brew')) return 'done';
    if(!startDeckRun('brew')) say('This deck has no cards yet.');
    return 'render';
  }
  if(act === 'brew-group'){
    const g = data.k === 'all' || brewGroup(data.k) ? data.k : 'all';
    brewState().group = g;
    return 'render';
  }
  if(act === 'brew-house'){
    if(typeof houseStudyOpenFrom === 'function' && houseStudyOpenFrom(data.id)) return 'render';
    say('That drink is not in the current house menu.');
    return 'done';
  }
  if(act === 'brew-lib'){
    if(typeof COFFEE_STUDY === 'undefined' || !COFFEE_STUDY.some(function(s){ return s.key === data.sec; })) return 'done';
    const row = data.row !== undefined && data.row !== '' ? Number(data.row) : null;
    state.tab = 'coffee';
    state.coffee = { sec: data.sec, rowOpen: row !== null && Number.isFinite(row) ? row : null, refOpen: data.ref || null };
    brewState().libJump = data.ref ? 'ref' : 'row';
    return 'render';
  }
  return null;
}
function brewAfterRender(){
  if(typeof document === 'undefined') return;
  const input = document.getElementById('brew-q');
  if(input && !input.__brew){
    input.__brew = true;
    input.addEventListener('input', function(){
      brewState().q = input.value;
      const out = document.getElementById('brew-results');
      if(out) out.innerHTML = brewResultsHTML();
    });
  }
  /* a Library link: the lesson or the card it opened, brought into sight
     clear of the sticky Back, as the house's jumps are (hsJump) */
  const s = brewState();
  if(s.libJump){
    const jump = s.libJump; s.libJump = '';
    if(state.tab === 'coffee'){
      const el = document.querySelector(jump === 'ref' ? '#cof-refs [data-act="cof-ref"][aria-expanded="true"]' : '[data-act="cof-row"][aria-expanded="true"]');
      if(el){ try {
        const back = document.querySelector('#view .backrow');
        const y = el.getBoundingClientRect().top + (window.scrollY || window.pageYOffset || 0);
        window.scrollTo(0, Math.max(0, Math.round(y - (back ? back.offsetHeight : 0) - 8)));
        el.focus({ preventScroll: true });
      } catch(e){} }
    }
  }
}
function brewSearchEntries(){
  return [{ t: 'Coffee and tea', s: 'Every coffee and tea a guest may ask for', body: 'coffee tea espresso latte cappuccino americano cafe au lait chai matcha', h: brewHref() }]
    .concat(brewEntries().map(function(e){ return { t: e.name, s: 'Coffee and tea \u00b7 ' + brewGroupTitle(e.group), body: brewSearchText(e), h: brewHref(e.id) }; }));
}
function brewOwnsKey(e){ return !!(e && e.target && e.target.closest && e.target.closest('.brew-index, .brew-detail, .brew-read-link')); }
